<script setup lang="ts">
import { Radio,Skull,ArrowRight,Play,ShieldCheck,Settings2,Home } from '@lucide/vue'
import { ref } from 'vue'
import type { GameState,ScreenState } from '@/types/game'
import SettingsPanel from '@/components/SettingsPanel.vue'
const props=defineProps<{screen:ScreenState;state:Readonly<GameState>}>()
const emit=defineEmits<{start:[];resume:[];menu:[];configure:[]}>();const showSettings=ref(false)
const time=(s:number)=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`
</script>
<template><div v-if="['paused','gameover','victory'].includes(props.screen)" class="modal-backdrop" data-testid="session-overlay"><section v-if="showSettings&&screen==='paused'" class="dialog-panel pause-settings" role="dialog" aria-modal="true" aria-label="Configuración en pausa"><button data-testid="pause-settings-back" class="secondary" @click="showSettings=false">Volver a pausa</button><SettingsPanel @change="emit('configure')"/></section><section v-else class="dialog-panel session-panel" role="dialog" aria-modal="true" aria-labelledby="session-title"><span class="session-icon"><Radio v-if="screen==='paused'"/><ShieldCheck v-else-if="screen==='victory'"/><Skull v-else/></span><div class="section-kicker">{{screen==='paused'?'OPERACIÓN EN ESPERA':screen==='victory'?'EXTRACCIÓN CONFIRMADA':'FIN DE LA TRANSMISIÓN'}}</div><h2 id="session-title">{{screen==='paused'?'TOMA AIRE':screen==='victory'?'VOLVISTE CON VIDA':'SEÑAL PERDIDA'}}<span>.</span></h2><p class="muted">{{screen==='paused'?'La horda puede esperar. Tu operación sigue aquí.':screen==='victory'?'El coloso cayó. Tu equipo vuelve a casa.':'La noche ganó esta vez. Tu próxima guardia empieza aquí.'}}</p><div class="session-stats"><div><strong>{{time(state.elapsed)}}</strong><span>TIEMPO CON VIDA</span></div><div><strong>{{state.wave.toString().padStart(2,'0')}}</strong><span>RONDA</span></div><div><strong>{{state.kills}}</strong><span>BAJAS</span></div></div><button v-if="screen==='paused'" data-testid="resume-button" class="primary wide" @click="emit('resume')"><Play :size="18"/>CONTINUAR OPERACIÓN<ArrowRight :size="19"/></button><button v-else data-testid="restart-button" class="primary wide" @click="emit('start')"><Play :size="18"/>{{screen==='victory'?'NUEVA OPERACIÓN':'VOLVER A INTENTAR'}}<ArrowRight :size="19"/></button><button v-if="screen==='paused'" data-testid="pause-settings" class="secondary wide" @click="showSettings=true"><Settings2 :size="16"/>Ajustes avanzados</button><button data-testid="menu-button" class="secondary wide" @click="showSettings=false;emit('menu')"><Home :size="16"/>VOLVER AL LOBBY</button><small v-if="screen==='paused'" class="muted">Volver al lobby termina la operación actual. Tu equipo y conjuntos se conservan.</small></section></div></template>
